import crypto from "crypto";
import type { Request, Response, NextFunction } from "express";
import { MerchantKeyStore, MerchantKey } from "./merchantKeys";

const SIGNATURE_HEADER = "x-billing-signature";
const TIMESTAMP_HEADER = "x-billing-timestamp";
const KEY_ID_HEADER = "x-billing-key-id";
const TOLERANCE_SECONDS = 300;

export interface AuthenticatedRequest extends Request {
  merchantId?: string;
  rawBody?: Buffer;
}

export function computeSignature(secret: string, timestamp: string, body: Buffer): string {
  return crypto
    .createHmac("sha256", secret)
    .update(`${timestamp}.`)
    .update(body)
    .digest("hex");
}

function safeEqualHex(a: string, b: string): boolean {
  const left = Buffer.from(a, "hex");
  const right = Buffer.from(b, "hex");
  if (left.length === 0 || left.length !== right.length) {
    return false;
  }
  return crypto.timingSafeEqual(left, right);
}

export function merchantSignatureAuth(keys: MerchantKeyStore) {
  return async (req: AuthenticatedRequest, res: Response, next: NextFunction) => {
    const keyId = req.header(KEY_ID_HEADER);
    const timestamp = req.header(TIMESTAMP_HEADER);
    const signature = req.header(SIGNATURE_HEADER);

    if (!keyId || !timestamp || !signature) {
      return res.status(401).json({ error: "missing_credentials" });
    }

    const ts = Number(timestamp);
    if (!Number.isInteger(ts)) {
      return res.status(401).json({ error: "invalid_timestamp" });
    }

    const nowSeconds = Math.floor(Date.now() / 1000);
    if (nowSeconds - ts > TOLERANCE_SECONDS) {
      return res.status(401).json({ error: "stale_request" });
    }

    let key: MerchantKey | null;
    try {
      key = await keys.findActive(keyId);
    } catch (err) {
      req.log?.error({ err, keyId }, "merchant key lookup failed");
      return res.status(503).json({ error: "auth_unavailable" });
    }

    if (!key) {
      return res.status(401).json({ error: "invalid_credentials" });
    }

    const body = req.rawBody ?? Buffer.alloc(0);
    const expected = computeSignature(key.secret, timestamp, body);
    if (!safeEqualHex(signature, expected)) {
      return res.status(401).json({ error: "invalid_credentials" });
    }

    req.merchantId = key.merchantId;
    next();
  };
}

import type { Pool } from "pg";

export interface MerchantKey {
  keyId: string;
  merchantId: string;
  secret: string;
  revokedAt: Date | null;
}

export interface MerchantKeyStore {
  findActive(keyId: string): Promise<MerchantKey | null>;
}

export class PgMerchantKeyStore implements MerchantKeyStore {
  constructor(private readonly pool: Pool) {}

  async findActive(keyId: string): Promise<MerchantKey | null> {
    const { rows } = await this.pool.query(
      `SELECT key_id, merchant_id, secret, revoked_at
         FROM merchant_api_keys
        WHERE key_id = $1 AND revoked_at IS NULL`,
      [keyId]
    );
    if (rows.length === 0) return null;
    const r = rows[0];
    return {
      keyId: r.key_id,
      merchantId: r.merchant_id,
      secret: r.secret,
      revokedAt: r.revoked_at,
    };
  }
}

import express from "express";
import { merchantSignatureAuth, AuthenticatedRequest } from "./signatureAuth";
import { PgMerchantKeyStore } from "./merchantKeys";
import { pool } from "./db";
import { createCharge } from "./charges";

const app = express();

app.use(
  express.json({
    verify: (req, _res, buf) => {
      (req as AuthenticatedRequest).rawBody = Buffer.from(buf);
    },
  })
);

const auth = merchantSignatureAuth(new PgMerchantKeyStore(pool));

app.post("/v1/charges", auth, async (req: AuthenticatedRequest, res) => {
  const charge = await createCharge(req.merchantId!, req.body);
  res.status(201).json(charge);
});

export default app;
